buttonColor:
{{
  (Get_Alertes_Controle_Loc.data || []).some(m => m.Alerte_Entretien?.includes('72h'))
    ? '#de1717'   // 🔴 Rouge vif si au moins une machine repart sous 72 h
    : '#d45125'   // 🟠 Orange si pas de réservation immédiate
}}

onClick:
{{
  (async function() {
    await storeValue('tab_location', '🚜 Flotte & Matériel');
    await storeValue('page_precedente', '🛠️ Atelier Global');
    await navigateTo('🔑 Location');
  })()
}}

text:
{{
  (() => {
    const data = Get_Alertes_Controle_Loc.data || [];
    const urgents = data.filter(m => m.Alerte_Entretien?.includes('72h')).length;
    const standards = data.length - urgents;

    if (urgents > 0) {
      return `🚨 ${urgents} Loc URGENTE (< 72h)${standards > 0 ? ` (+${standards})` : ''}`;
    }
    return `🧽 ${standards} Loc à contrôler`;
  })()
}}
